name: Auto-triage new issues
on:
  issues:
    types: [opened]

permissions:
  issues: write

jobs:
  triage-issue:
    runs-on: ubuntu-latest
    steps:
      - name: Bootstrap labels
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const labels = [
              { name: 'bug', color: 'e11d21' },
              { name: 'feature-request', color: '84b6eb' },
              { name: 'priority: high', color: 'eb6420' },
              { name: 'priority: medium', color: 'fef2c0' },
              { name: 'priority: low', color: '009800' }
            ];

            for (const label of labels) {
              try {
                await github.rest.issues.createLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  name: label.name,
                  color: label.color
                });
              } catch (error) {
                if (!error.message.includes('already exists')) {
                  throw error;
                }
              }
            }

      - name: Classify issue
        id: classify
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const issue = context.payload.issue;
            const title = issue.title.toLowerCase();
            const body = issue.body ? issue.body.toLowerCase() : '';
            const content = `${title} ${body}`;

            let type = 'feature-request';
            let priority = 'medium';

            const bugKeywords = ['bug', 'error', 'crash', 'broken', 'fix', 'fail', 'wrong', 'regression'];
            const featureKeywords = ['feat', 'feature', 'enhancement', 'add', 'implement', 'request', 'improve'];
            const highPriorityKeywords = ['critical', 'urgent', 'blocker', 'blocking', 'severe', 'p0', 'p1'];
            const lowPriorityKeywords = ['minor', 'trivial', 'nice to have', 'low priority', 'p3', 'p4'];

            // Determine type
            if (bugKeywords.some(keyword => content.includes(keyword))) {
              type = 'bug';
            } else if (featureKeywords.some(keyword => content.includes(keyword))) {
              type = 'feature-request';
            }

            // Determine priority
            if (highPriorityKeywords.some(keyword => content.includes(keyword))) {
              priority = 'high';
            } else if (lowPriorityKeywords.some(keyword => content.includes(keyword))) {
              priority = 'low';
            }

            // Set outputs
            core.setOutput('type', type);
            core.setOutput('priority', priority);

      - name: Apply labels
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const typeLabel = '${{ steps.classify.outputs.type }}';
            const priorityLabel = '${{ steps.classify.outputs.priority }}';

            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: [typeLabel, priorityLabel]
            });
